entries[40767] = { ["name"] = "Sonic Booster", ["text"] = "Binds when equipped\nTrinket\n+81 Stamina\nRequires Engineering (390)\nEquip: The noise made from melee combat sometimes causes Sonic Awareness, increasing your attack power by 430 for 10 sec. This effect can only occur once every minute. (Proc chance: 35%, 50s cooldown)\nSell Price: 6 79 49" }
entries[40768] = { ["name"] = "MOLL-E", ["text"] = "Toy\nRequires Engineering (425)\nUse: Creates a portable mailbox for 10 min. MOLL-E is not destroyed after use. (2 Hrs Cooldown)\n\"Mobile Oversized Letter and Literary Extractor\"" }
entries[40769] = { ["name"] = "Scrapbot Construction Kit", ["text"] = "Requires Engineering (425)\nUse: Creates a mechanical Scrapbot that repairs equipment and buys nearly anything. The scrapbot leaves after 5 min. (15 Min Cooldown)\nSell Price: 18 75" }
entries[40771] = { ["name"] = "Cobalt Frag Bomb", ["text"] = "Requires Engineering (330)\nUse: Inflicts 750 to 1000 Fire damage and incapacitates targets for 3 sec in a 3 yard radius. Any damage will break the effect. (1 Min Cooldown)\nSell Price: 6" }
entries[40772] = { ["name"] = "Gnomish Army Knife", ["text"] = "Use: A grand master engineer can overload the knife's battery to attempt to shock a dead player back to life. Cannot be used in combat. (30 Min Cooldown)\n\"Includes Gyromatic Micro-Adjuster, Arclight Spanner, Flint and Tinder, Blacksmithing Hammer, Mining Pick, and a Skinning Knife.\"Sell Price: 22 56" }
entries[40773] = { ["name"] = "Master Firestone", ["text"] = "Binds when picked up\nUnique\nUse: While applied to target weapon it increases damage dealt by direct spells by 1% and spell critical strike rating by 35. Lasts for 1 hour.\n5 Charges" }
entries[40775] = { ["name"] = "Winged Steed of the Ebon Blade", ["text"] = "Binds when picked up\nUnique\nMountClasses: Death Knight\nRequires Level 60\nRequires Riding (225)\nUse: Speed scales to riding skill.\nSummons and dismisses your Winged Steed of the Ebon Blade. This mount can only be summoned in Outland and Northrend. This mount changes speed depending on your Riding skill." }
entries[40776] = { ["name"] = "Personal Electromagnetic Pulse Generator", ["text"] = "Requires Engineering (375)\nUse: Permanently attaches a high-powered device to your belt, allowing you to confuse nearby mechanicals. Only a skilled engineer can activate the modified belt.\n\nCan only be attached to your own belt, and doing so causes the belt to become soulbound.\nSell Price: 12 50" }
entries[40777] = { ["name"] = "Polar Bear Harness", ["text"] = "Binds when picked up\nMount\nRequires Level 60\nRequires Riding (150)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable White Polar Bear. This is a very fast mount." }
